mapper.select:
SELECT r.meme_id AS memeId, t.id AS id, t.name AS name, t.category AS category, r.is_primary AS isPrimary, t.related_quantity AS relatedQuantity FROM meme_tag_relation r INNER JOIN meme_tag t ON r.meme_tag_id = t.id WHERE r.meme_id IN
#{memeId}
ORDER BY r.meme_id ASC, r.is_primary DESC, t.category ASC, t.sort_order ASC, t.id ASC
